# Configuration validation utilities

def validate_config(settings):
    # TODO: add schema-based validation
    errors = []
    if not settings:
        errors.append('Empty configuration')
    # FIXME: handle nested dicts properly
    return errors

def load_and_validate(path):
    # FIXME: catch FileNotFound gracefully
    with open(path) as f:
        data = f.read()
    return validate_config(data)
